package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for RandomStringUtils.randomAscii(int count)
 */
public class RandomStringUtils_randomAscii_TriageGen2Test {

    @Test
    public void testRandomAscii_PositiveCount() {
        int count = 10;
        String result = RandomStringUtils.randomAscii(count);
        assertNotNull("Result should not be null", result);
        assertEquals("Result length should match the requested count", count, result.length());

        // Verify all characters are within the ASCII range (32 to 126)
        // Note: The method signature uses 32 to 127, but 127 is DEL. 
        // We check if every character is within the specified bounds.
        for (int i = 0; i < result.length(); i++) {
            char c = result.charAt(i);
            assertTrue("Character '" + c + "' should be in ASCII range [32, 126]", c >= 32 && c <= 126);
        }
    }








}

