package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for RandomStringUtils.randomAscii(int count)
 */
public class RandomStringUtils_randomAscii_TriageGen2Test {









    @Test
    public void testRandomAscii_Uniqueness() {
        // Statistical test: two calls with same count should likely produce different strings
        int count = 20;
        String result1 = RandomStringUtils.randomAscii(count);
        String result2 = RandomStringUtils.randomAscii(count);
        assertNotEquals("Two random strings should not be identical", result1, result2);
    }
}
